from research_helpers import *
a=ev('https://hub.tech/en/history/','Issuer confirms Boruta-Zachem rename to Hub.Tech and biosurfactant production history.')
b=ev('https://hub.tech/relacje-inwestorskie/','Issuer confirms completed acquisition of 60 percent of InventionBio December 2020; group product association uses commercial partner role.')
c=ev('https://inventionbio.pl/en/products/','Reviewed full subsidiary product catalogue. Eight named fermentation/carrier ingredients plus ActiMeal and BioProTex; standard non-fermented plant oil not automatically biotechnology.')
products=[]
for name,desc in [('InBioNano','Biosurfactant-based nanoscale carrier for encapsulation and delivery of active ingredients.'),('InBioLev','Levan-rich fermentation-derived biopolymer ingredient.'),('InBioSur','Bacillus subtilis biorefinery-derived biosurfactant ingredient.'),('InBioPGA','Fermentation-derived polyglutamic acid ingredient.'),('InBioYeast Extract','Saccharomyces-derived ingredient produced through yeast autolysis.'),('InBioBacFiltrate','Bacillus subtilis fermentation culture filtrate ingredient.'),('InBioComb','Green-tea fermentation-derived ingredient.'),('InBioFerLys','Probiotic bacterial cell lysate ingredient.'),('ActiMeal','Bacillus subtilis 87Y-fermented rapeseed meal feed product.')]:
 products.append(p(name,desc,c,'commercial',roles=['commercial_partner'],typ='product',sub='industrial_biotechnology',evidence=[b,c]))
products.append(p('BioProTex','Bacillus subtilis Y86 probiotic carrier product intended for animal production; catalogue describes registration preparation rather than confirmed market authorization.',c,'development',roles=['commercial_partner'],typ='product',sub='industrial_biotechnology',evidence=[b,c]))
co=dict(company_id='cmp_0a28acaa-3534-465e-ac49-848adbb1b91b',products=products,evidence=[a,b,c],status='partial',coverage_note='Ten explicit subsidiary biotechnology products recorded, using parent commercial partner role. No therapeutic efficacy/approval inferred from ingredient marketing. Partial: continued group ownership, current commercialization of prospective BioProTex, specific biosurfactant grades and other legacy/subsidiary biorefinery technologies remain. Ordinary dyes, pigments and finished cosmetic ranges not automatically biotechnology.')
(out/'batch-0230.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
